const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hotan = ee.Geometry.Point([79.9269, 37.0998]); // Hotan coordinates
  const region = hotan.buffer(5000); // 5km buffer around Hotan

  const date1 = '2020-02-23';
  const date2 = '2020-04-29';
  const dateRange = 7; // ±7 days window

  // 2. Data Acquisition - Sentinel-2 for vegetation monitoring
  function getSentinel2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));
  }

  // Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // NDVI calculation
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Get collections for both periods
  const col1 = getSentinel2Collection(
    ee.Date(date1).advance(-dateRange, 'day'),
    ee.Date(date1).advance(dateRange, 'day')
  ).map(maskClouds).map(addNDVI);

  const col2 = getSentinel2Collection(
    ee.Date(date2).advance(-dateRange, 'day'), 
    ee.Date(date2).advance(dateRange, 'day')
  ).map(maskClouds).map(addNDVI);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Feb 2020 Images: ${size1}, Apr 2020 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const img1 = col1.median().select('NDVI');
  const img2 = col2.median().select('NDVI');

  // Calculate mean NDVI values
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  });

  const ndvi1 = stats1.get('NDVI').getInfo();
  const ndvi2 = stats2.get('NDVI').getInfo();

  // Check for valid pixels
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb NDVI: ${ndvi1?.toFixed(4)}, Pixels: ${count1}`);
  console.log(`Apr NDVI: ${ndvi2?.toFixed(4)}, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Validate calculations
  if (ndvi1 === null || ndvi2 === null || 
      isNaN(ndvi1) || isNaN(ndvi2) ||
      ndvi1 < -1 || ndvi1 > 1 || ndvi2 < -1 || ndvi2 > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine if vegetation increased (threshold = 0.01 for desert environment)
  const increase = ndvi2 - ndvi1 > 0.01;
  console.log(`NDVI Change: ${(ndvi2 - ndvi1).toFixed(4)}`);

  if (increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
